<p class="eyebrow"><?= $e($t('TRANSPARENT ALLOCATIONS · PRIVATE DESK')) ?></p><h1><?= $e($t('ledger')) ?></h1><p><span class="demo-label"><?= $e($t('paymentDemo')) ?></span></p><p class="lead"><?= $e($t('Every share has a place.')) ?></p><p><?= $e($t('These are simulated allocations, not transfers or money owed by a payment provider. Currencies are kept separate.')) ?></p><div class="cards"><?php foreach ($ledger['totals'] as $currency => $amount): ?><article class="card stat"><span class="badge">Demo allocation</span><h2><?= $e($money($amount, $currency)) ?></h2><p><?= $e($t('Net simulated allocation')) ?></p></article><?php endforeach ?></div><section class="card"><h2><?= $e($t('Contributor balances')) ?></h2><?php foreach ($ledger['balances'] as $balance): ?><div class="share-row"><span><?= $e($balance['name']) ?></span><strong><?= $e($money($balance['amountMinor'], $balance['currency'])) ?></strong></div><?php endforeach ?><?php if (!$ledger['entries']): ?><p class="empty"><?= $e($t('No demo entries yet. Approve a commercial request with an agreed fee to see allocations here.')) ?></p><?php endif ?></section><section><h2><?= $e($t('Transaction history')) ?></h2><?php foreach ($ledger['entries'] as $entry): ?><article class="card"><div class="card-top"><span class="badge"><?= $e(\Passport\Copy::ledgerKind($entry['kind'])) ?></span><span class="mono"><?= $e($entry['story_id']) ?></span></div><h3><?= $e($entry['contributor_name']) ?> · <?= $e($money($entry['amount_minor'], $entry['currency'])) ?></h3><p><?= $e(\Passport\Copy::ledgerNote($entry['note'])) ?></p><p class="muted"><?= $e($entry['created_at']) ?> UTC</p><?php if ($entry['original_entry_id']): ?><p class="mono"><?= $e($t('Adjusts entry')) ?> <?= $e($entry['original_entry_id']) ?></p><?php endif ?><?php if ($canEdit($entry['story_id'])): ?><details><summary><?= $e($t('Append a demo correction')) ?></summary><form data-api="/api/ledger/<?= $e($entry['id']) ?>/adjustments" data-reload><label><?= $e($t('Signed demo adjustment (minor units)')) ?><input type="number" name="amountMinor" min="-1000000000" max="1000000000" step="1" required data-int></label><label><?= $e($t('Reason')) ?><textarea name="note" required maxlength="2000"></textarea></label><button class="button secondary"><?= $e($t('Append correction')) ?></button><p class="form-message" role="status" aria-live="polite"></p></form></details><?php endif ?></article><?php endforeach ?></section>


